#include <cstdio>

int main() {
    int a, b;
    scanf("%d %d", &a, &b);

    if (a == 0 && b == 0) {
        printf("NO\n");
        return 0;
    }

    int difference = a - b;
    if (difference >= -1 && difference <= 1)
        printf("YES\n");
    else
        printf("NO\n");

    return 0;
}

